import React from 'react';

const Footer = () => {
    return (
        <footer className="bg-dark text-white text-center py-3">
            <div className="container">
                <div className="row">
                    <div className="col">
                        <a href="#">Link 1</a>
                    </div>
                    <div className="col">
                        <a href="#">Link 2</a>
                    </div>
                    <div className="col">
                        <a href="#">Link 3</a>
                    </div>
                </div>
            </div>
        </footer>
    );
};

export default Footer;
